#!/usr/bin/env bash
# @domain: awareness
# @test-type: integration — needs today's door (:3360) and pulse-api running; reports
# UNMEASURED, never green or red, when either is down.
#
# #4490 — pulse-api (directing/products/pulse/api, generated by
# designing/services/athena-gen) answers every pulse route the same as today's door:
# same rows, same names, same field values. Run before any caller moves off v1.
# pulse-api runs from directing/products/pulse/api/pulse-api-launch.sh (LaunchAgent
# com.chorus.pulse-api); the check below also proves that wrapper starts nothing secret-shaped.
set -u
V1="${V1_URL:-http://localhost:3360}"
V2="${PULSE_API_URL:-http://127.0.0.1:3392}"
ROUTES="awareness/rolestates awareness/heartbeats awareness/readings awareness/waitingons streams/events"
compare() { # v1-json v2-json → prints diffs, exit 1 on any
  python3 - "$1" "$2" <<'PY'
import json, sys
a, b = json.load(open(sys.argv[1])), json.load(open(sys.argv[2]))
da = {x["name"]: x for x in a.get("data", [])}
db = {x["name"]: x for x in b.get("data", [])}
diffs = []
for n in sorted(set(da) | set(db)):
    x, y = da.get(n), db.get(n)
    if x is None or y is None:
        diffs.append(f"{n}: only in {'v1' if y is None else 'pulse-api'}")
        continue
    for k in sorted(set(x) | set(y)):
        if x.get(k) != y.get(k):
            diffs.append(f"{n}.{k}: v1={x.get(k)!r} pulse-api={y.get(k)!r}")
for d in diffs:
    print("  ", d)
print(f"rows {len(da)}/{len(db)}, {len(diffs)} differences")
sys.exit(1 if diffs else 0)
PY
}
LAUNCH="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)/directing/products/pulse/api/pulse-api-launch.sh"
bash -n "$LAUNCH" || { echo "FAIL: pulse-api-launch.sh does not parse"; exit 1; }
if grep -qE 'echo.*(PASSWORD|USER)|set -x' "$LAUNCH"; then echo "FAIL: pulse-api-launch.sh could print a credential"; exit 1; fi
# the LaunchAgent (platform/scripts/launchagents-canonical/com.chorus.pulse-api.plist) runs the
# wrapper and carries no credential, only paths (Silas's review, 2026-10-10)
PLIST="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)/platform/scripts/launchagents-canonical/com.chorus.pulse-api.plist"
grep -q '/.chorus/bin/pulse-api-launch.sh' "$PLIST" || { echo "FAIL: the pulse-api LaunchAgent does not run its launch wrapper"; exit 1; }
if grep -qiE 'PASSWORD|SECRET|TOKEN' "$PLIST"; then echo "FAIL: the pulse-api LaunchAgent names a credential"; exit 1; fi
if [ "${1:-}" = "--self-test" ]; then
  # NEGATIVE PROOF: two answers that differ in one field must be reported as different
  T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
  echo '{"data":[{"name":"wren","stateValue":"waiting"}]}' > "$T/a"
  echo '{"data":[{"name":"wren","stateValue":"idle"}]}' > "$T/b"
  if compare "$T/a" "$T/b" >/dev/null; then echo "FAIL NEGATIVE: a differing field passed"; exit 1; fi
  if ! compare "$T/a" "$T/a" >/dev/null; then echo "FAIL: identical answers reported different"; exit 1; fi
  echo "PASS self-test: a differing field is caught, identical answers pass"; exit 0
fi
curl -sf -m 5 "$V1/health" >/dev/null 2>&1 || curl -sf -m 5 "$V1/" >/dev/null 2>&1 || { echo "UNMEASURED: today's door not reachable at $V1"; exit 0; }
curl -sf -m 5 "$V2/health" >/dev/null 2>&1 || { echo "UNMEASURED: pulse-api not reachable at $V2"; exit 0; }
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
fail=0
for r in $ROUTES; do
  curl -sf -m 30 "$V1/v1/$r?limit=1000" > "$T/a" && curl -sf -m 30 "$V2/v1/$r?limit=1000" > "$T/b" || { echo "FAIL $r: a route did not answer"; fail=1; continue; }
  if out=$(compare "$T/a" "$T/b"); then echo "PASS $r: $out"; else echo "FAIL $r:"; echo "$out"; fail=1; fi
done
exit $fail
